"use client";
import { useMemo } from "react";
import { Combobox as ComboboxPrimitive } from "@base-ui/react/combobox";
import { Check, ChevronDown, X } from "lucide-react";
import { inputClasses } from "@/components/ui/input";
import { cn } from "@/lib/utils";
export type ComboboxOption = { value: string; label: string };
export function Combobox({
  options,
  value,
  onValueChange,
  label,
  placeholder,
  emptyLabel = "No options found",
  disabled,
  className,
  id,
}: {
  options: ComboboxOption[];
  value?: string | null;
  onValueChange: (value: string | null) => void;
  label: string;
  placeholder?: string;
  emptyLabel?: string;
  disabled?: boolean;
  className?: string;
  id?: string;
}) {
  const items = useMemo(
    () =>
      ComboboxPrimitive.createItems(options, {
        getValue: (o) => o.value,
        getLabel: (o) => o.label,
      }),
    [options],
  );
  return (
    <ComboboxPrimitive.Root
      items={items}
      value={value ?? null}
      onValueChange={onValueChange}
      disabled={disabled}
    >
      <ComboboxPrimitive.InputGroup className={cn("relative", className)}>
        <ComboboxPrimitive.Input
          id={id}
          aria-label={label}
          placeholder={placeholder}
          className={cn(inputClasses, "pr-16")}
        />
        <div className="absolute inset-y-0 right-2 flex items-center gap-1">
          <ComboboxPrimitive.Clear
            aria-label={label}
            className="rounded p-1 text-muted-foreground"
          >
            <X className="size-3" />
          </ComboboxPrimitive.Clear>
          <ComboboxPrimitive.Trigger
            aria-label={label}
            className="rounded p-1 text-muted-foreground"
          >
            <ChevronDown className="size-3.5" />
          </ComboboxPrimitive.Trigger>
        </div>
      </ComboboxPrimitive.InputGroup>
      <ComboboxPrimitive.Portal>
        <ComboboxPrimitive.Positioner sideOffset={6} className="z-70">
          <ComboboxPrimitive.Popup className="min-w-(--anchor-width) max-h-72 overflow-auto rounded-lg border border-border bg-surface p-1 text-foreground shadow-lg">
            <ComboboxPrimitive.Empty className="p-4 text-xs text-muted-foreground">
              {emptyLabel}
            </ComboboxPrimitive.Empty>
            <ComboboxPrimitive.List>
              {(option: ComboboxOption) => (
                <ComboboxPrimitive.Item
                  key={option.value}
                  value={option.value}
                  className="flex items-center justify-between gap-4 rounded-md px-3 py-2 text-xs outline-none data-highlighted:bg-accent"
                >
                  {option.label}
                  <ComboboxPrimitive.ItemIndicator>
                    <Check className="size-3.5" />
                  </ComboboxPrimitive.ItemIndicator>
                </ComboboxPrimitive.Item>
              )}
            </ComboboxPrimitive.List>
          </ComboboxPrimitive.Popup>
        </ComboboxPrimitive.Positioner>
      </ComboboxPrimitive.Portal>
    </ComboboxPrimitive.Root>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
export const inputClasses =
  "af-input flex h-[var(--af-control-height,40px)] w-full min-w-0 rounded-[var(--radius-md,10px)] border border-border bg-surface px-3.5 text-[13px] leading-6 text-foreground outline-none transition-[border-color,background-color,box-shadow] placeholder:text-muted-foreground hover:border-primary/35 focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/25 aria-invalid:border-destructive-foreground aria-invalid:ring-destructive-foreground/20 disabled:cursor-not-allowed disabled:opacity-50 disabled:hover:border-border file:mr-3 file:rounded-md file:border-0 file:bg-accent file:px-2 file:py-1 file:text-xs file:font-semibold file:text-accent-foreground";
export function Input({ className, ...props }: React.ComponentProps<"input">) {
  return (
    <input
      data-slot="input"
      className={cn(inputClasses, className)}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}
